const STORE_KEY = 'mock.codx.teamView'
function loadDB(){ try{ const raw = localStorage.getItem(STORE_KEY); return raw ? JSON.parse(raw) : structuredClone(SEED) }catch{ return structuredClone(SEED) } }
let DB = loadDB()
function persistDB(){ try{ localStorage.setItem(STORE_KEY, JSON.stringify(DB)) }catch{} }
function resetDB(){ localStorage.removeItem(STORE_KEY); DB = structuredClone(SEED) }

/* ── B. MOCK SERVER  ───────────────────────────────────────────────── */
const json = (data,status=200)=> new Response(JSON.stringify(data),{status,headers:{'Content-Type':'application/json'}})

const routes = [
  { m:'GET',    r:/^\/api\/profiles$/,        h:()=>DB.members },
  { m:'POST',   r:/^\/api\/profiles$/,        h:({body})=>{
      const existing = DB.members.find(x=>x.id===body.id)
      if(existing){ Object.assign(existing, body); persistDB(); return existing }
      const member = { ...body, id: body.id || 'm_'+Date.now() }
      DB.members.push(member); persistDB(); return member } },
  { m:'GET',    r:/^\/api\/profiles\/([^/]+)$/, h:({params})=>DB.members.find(x=>x.id===params[0])||DB.members.find(x=>x.name===decodeURIComponent(params[0])) },
  { m:'DELETE', r:/^\/api\/profiles\/([^/]+)$/, h:({params})=>{
      DB.members = DB.members.filter(x=>x.id!==params[0]); persistDB(); return {ok:true} } },
  { m:'GET',    r:/^\/api\/profiles\/tools$/, h:()=>TOOLS },
  { m:'GET',    r:/^\/api\/projects\/ai\/models$/, h:()=>MODELS }
]

function mockFetch(input, init={}){
  const url = typeof input==='string' ? input : input.url
  const method = (init.method||'GET').toUpperCase()
  const { pathname, searchParams } = new URL(url, location.origin)
  const route = routes.find(rt=>rt.m===method && rt.r.test(pathname))
  return new Promise(resolve=>{
    setTimeout(()=>{
      // MOCK: optional forced failure for the error state (?_fail=1)
      if(searchParams.get('_fail')==='1') return resolve(json({error:'server_error'},500))
      if(!route) return resolve(json({error:'not_found'},404))
      const params = pathname.match(route.r)?.slice(1) ?? []
      let body = {}
      try{ body = init.body ? JSON.parse(init.body) : {} }catch{}
      const result = route.h({params, body})
      if(result==null) return resolve(json({error:'not_found'},404))
      resolve(json(result, method==='POST'?201:200))
    }, 180 + Math.random()*260)  // MOCK: simulated latency
  })
}

