/* ── D. HELPERS  ───────────────────────────────────────────────────── */
const esc = s => String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))
const teamById = id => TEAMS.find(t=>t.id===id) || null
const AV_COLORS = ['#6366f1','#22d3ee','#f59e0b','#10b981','#ef4444','#a78bfa','#3b82f6','#ec4899']
function avatarColor(name){ let h=0; for(const ch of name||'?') h=(h*31+ch.charCodeAt(0))%997; return AV_COLORS[h%AV_COLORS.length] }
function initials(name){ return (name||'?').split(/\s+/).map(w=>w[0]).slice(0,2).join('').toUpperCase() }
function avatarHTML(m, size=44){
  if(m.avatar) return `<img src="${esc(m.avatar)}" alt="${esc(m.name)}" style="width:${size}px;height:${size}px;border-radius:50%;object-fit:cover" onerror="this.replaceWith(Object.assign(document.createElement('div'),{textContent:'${esc(initials(m.name))}',style:'width:${size}px;height:${size}px;border-radius:50%;display:grid;place-items:center;font-weight:700;font-size:${Math.round(size*0.36)}px;color:#fff;background:${avatarColor(m.name)}'}))">`
  return `<div style="width:${size}px;height:${size}px;border-radius:50%;display:grid;place-items:center;font-weight:700;font-size:${Math.round(size*0.36)}px;color:#fff;background:${avatarColor(m.name)}">${esc(initials(m.name))}</div>`
}
function filtered(){
  const q = state.search.trim().toLowerCase()
  let list = state.members.filter(m=>{
    const okQ = !q || [m.name,m.description,m.category].join(' ').toLowerCase().includes(q)
    const okR = !state.roleFilter || m.category===state.roleFilter
    const okT = !state.teamFilter || m.teamId===state.teamFilter
    return okQ&&okR&&okT
  })
  const by = state.sort
  list.sort((a,b)=> by==='role'
      ? (roleMeta(a.category).label>roleMeta(b.category).label?1:-1)
      : (a.name>b.name?1:-1))
  return list
}
function membersOf(teamId){ return filtered().filter(m=>m.teamId===teamId) }

