function statsHTML(){
  const members = state.members
  const skills = new Set(members.flatMap(m=>m.tools||[])).size
  const know = members.filter(m=>m.use_knowledge).length
  const cells = [
    ['Members', members.length, 'users', 'var(--primary-lt)'],
    ['Teams', TEAMS.length, 'grid', 'var(--info)'],
    ['Skills in use', skills, 'wrench', 'var(--success)'],
    ['Knowledge-enabled', know, 'book', 'var(--warning)']
  ]
  return `<div class="grid grid-cols-2 lg:grid-cols-4 gap-3">
    ${cells.map(([label,val,ic,color])=>`<div class="card p-3 flex items-center gap-3">
      <div class="w-9 h-9 rounded-lg grid place-items-center" style="background:rgba(255,255,255,.04);color:${color}">${icon(ic,18)}</div>
      <div><div class="text-xl font-bold leading-none">${val}</div>
      <div class="text-[11px] text-[color:var(--text-muted)] mt-1">${label}</div></div>
    </div>`).join('')}
  </div>`
}

function rosterHTML(){
  // reviewer state previews
  if(state.sim==='loading') return skeletonHTML()
  if(state.sim==='error') return errorHTML()
  if(state.sim==='empty') return emptyHTML()
  if(state.status==='loading') return skeletonHTML()
  if(state.status==='error') return errorHTML()

  const list = filtered()
  if(!state.members.length) return emptyHTML()
  if(!list.length) return noResultsHTML()

  return state.view==='board' ? boardHTML(list) : gridHTML(list)
}

function gridHTML(list){
  const groups = TEAMS.map(t=>({ team:t, members:list.filter(m=>m.teamId===t.id) })).filter(g=>g.members.length)
  const unassigned = list.filter(m=>!teamById(m.teamId))
  if(unassigned.length) groups.push({ team:{ id:'', name:'Unassigned', color:'#71717a', icon:'info' }, members:unassigned })
  if(!groups.length) return emptyHTML()
  return groups.map(g=>`<section class="mt-5 first:mt-0">
    <div class="flex items-center gap-2 mb-3">
      <span class="dot" style="background:${g.team.color}"></span>
      <h2 class="font-semibold text-sm">${esc(g.team.name)}</h2>
      <span class="badge">${g.members.length}</span>
    </div>
    <div class="grid grid-cols-1 sm:grid-cols-2 xl:grid-cols-3 2xl:grid-cols-4 gap-4">
      ${g.members.map(m=>memberCardHTML(m)).join('')}
    </div>
  </section>`).join('')
}

